ON t.[SailingId] = s.[SailingId] AND t.[CategoryId] = s.[CategoryId]
WHEN MATCHED THEN UPDATE SET t.[PerNightCents] = s.[PerNightCents]
WHEN NOT MATCHED THEN INSERT ([SailingId], [CategoryId], [PerNightCents]) VALUES (s.[SailingId], s.[CategoryId], s.[PerNightCents]);
GO

